{"l":5742,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'heldigvis' på engelsk i '___, nobody was hurt'?","o":["suddenly","finally","luckily","sadly"],"a":"luckily","r":"'Luckily' = heldigvis."},
