{"l":6069,"g":7,"b":2,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'smid ud' på engelsk i 'Don't ___ the box'?","o":["throw away","put away","bring back","give away"],"a":"throw away","r":"'Throw away' = smide ud."},
